window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c7133db028d1e938"]={"versions": [{"id": "FIG-c7133db028d1e938", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokollspezifisches Bit- und Byte-Layout (Protokollpaket-Format / PDU-Layout) einer Service-Discovery-Option innerhalb des AUTOSAR Service Discovery (SD) Moduls. Das Diagramm spezifiziert die Serialisierungsstruktur der „IPv6 SD Endpoint Option“ über einem 32-Bit-Raster (Bit-Offsets 0 bis 31).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Option besteht aus standardisierten Feldern:</p>\n<ul class=\"fig-list\"><li><strong>Length (=0x0015)</strong>: 16 Bit (Bit 0 bis 15 im ersten Word), fester Wert 21 Byte Nutzdatenlänge.\n</li><li><strong>Type (=0x26)</strong>: 8 Bit (Bit 16 bis 23 im ersten Word), Kennung des Optionstyps für IPv6 SD Endpoints.\n</li><li><strong>Reserved (=0x00)</strong>: 8 Bit (Bit 24 bis 31 im ersten Word), reserviertes Byte.\n</li><li><strong>IPv6-Address [128bit]</strong>: 128 Bit (16 Byte, vier aufeinanderfolgende 32-Bit-Worte), enthält die IPv6-Unicast- oder Multicast-Adresse des Endpunkts.\n</li><li><strong>Reserved (=0x00)</strong>: 8 Bit (Bit 0 bis 7 im sechsten Word), weiteres reserviertes Byte.\n</li><li><strong>L4-Proto (UDP/…)</strong>: 8 Bit (Bit 8 bis 15 im sechsten Word), Transportprotokollkennung (z. B. UDP).\n</li><li><strong>Port Number</strong>: 16 Bit (Bit 16 bis 31 im sechsten Word), L4-Portnummer des Endpunkts.\n</li></ul>\n<p class=\"fig-p\">Eine vertikale Maßlinie an der rechten Seite („Covered by Length (incl. Reserved)“) spannt über alle Felder ab der IPv6-Adresse bis einschließlich Port Number (Gesamtlänge 21 Byte bzw. 168 Bit).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische PDU-Feldbelegung ohne dynamische Kontrollfluss- oder Zustandsübergangssequenzen. Die Option wird als strukturierter Block innerhalb der Options-Sektion einer SOME/IP-SD-Nachricht serialisiert und deserialisiert. Der Sender codiert die IP-Adresse, das Transportprotokoll und den Zielport; der Empfänger wertet diese Daten zur Adressierung von Services oder Eventgruppen aus.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der Wire-Repräsentation der IPv6 SD Endpoint Option. Der Type-Identifikator ist zwingend auf 0x26 festgelegt. Das Längenfeld Length ist fest auf 0x0015 (21 Dezimal) codiert und deckt definitionsgemäß die nachfolgenden Felder ab: IPv6-Adresse (16 Byte) + Reserved (1 Byte) + L4-Proto (1 Byte) + Port Number (2 Byte) = 20 Byte zuzüglich des einleitenden Reserved-Bytes (1 Byte) = 21 Byte. Reservierte Felder müssen auf 0x00 gesetzt und beim Empfang ignoriert bzw. maskiert werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-51aaf938ad360e0e", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokollspezifisches Bit- und Byte-Layout (Protokollpaket-Format / PDU-Layout) einer Service-Discovery-Option innerhalb des AUTOSAR Service Discovery (SD) Moduls. Das Diagramm spezifiziert die Serialisierungsstruktur der „IPv6 SD Endpoint Option“ über einem 32-Bit-Raster (Bit-Offsets 0 bis 31).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Option besteht aus standardisierten Feldern:</p>\n<ul class=\"fig-list\"><li><strong>Length (=0x0015)</strong>: 16 Bit (Bit 0 bis 15 im ersten Word), fester Wert 21 Byte Nutzdatenlänge.\n</li><li><strong>Type (=0x26)</strong>: 8 Bit (Bit 16 bis 23 im ersten Word), Kennung des Optionstyps für IPv6 SD Endpoints.\n</li><li><strong>Reserved (=0x00)</strong>: 8 Bit (Bit 24 bis 31 im ersten Word), reserviertes Byte.\n</li><li><strong>IPv6-Address [128bit]</strong>: 128 Bit (16 Byte, vier aufeinanderfolgende 32-Bit-Worte), enthält die IPv6-Unicast- oder Multicast-Adresse des Endpunkts.\n</li><li><strong>Reserved (=0x00)</strong>: 8 Bit (Bit 0 bis 7 im sechsten Word), weiteres reserviertes Byte.\n</li><li><strong>L4-Proto (UDP/…)</strong>: 8 Bit (Bit 8 bis 15 im sechsten Word), Transportprotokollkennung (z. B. UDP).\n</li><li><strong>Port Number</strong>: 16 Bit (Bit 16 bis 31 im sechsten Word), L4-Portnummer des Endpunkts.\n</li></ul>\n<p class=\"fig-p\">Eine vertikale Maßlinie an der rechten Seite („Covered by Length (incl. Reserved)“) spannt über alle Felder ab der IPv6-Adresse bis einschließlich Port Number (Gesamtlänge 21 Byte bzw. 168 Bit).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische PDU-Feldbelegung ohne dynamische Kontrollfluss- oder Zustandsübergangssequenzen. Die Option wird als strukturierter Block innerhalb der Options-Sektion einer SOME/IP-SD-Nachricht serialisiert und deserialisiert. Der Sender codiert die IP-Adresse, das Transportprotokoll und den Zielport; der Empfänger wertet diese Daten zur Adressierung von Services oder Eventgruppen aus.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der Wire-Repräsentation der IPv6 SD Endpoint Option. Der Type-Identifikator ist zwingend auf 0x26 festgelegt. Das Längenfeld Length ist fest auf 0x0015 (21 Dezimal) codiert und deckt definitionsgemäß die nachfolgenden Felder ab: IPv6-Adresse (16 Byte) + Reserved (1 Byte) + L4-Proto (1 Byte) + Port Number (2 Byte) = 20 Byte zuzüglich des einleitenden Reserved-Bytes (1 Byte) = 21 Byte. Reservierte Felder müssen auf 0x00 gesetzt und beim Empfang ignoriert bzw. maskiert werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-248db2caf0c8b86c", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Protokollspezifisches Bit- und Byte-Layout (Protokollpaket-Format / PDU-Layout) einer Service-Discovery-Option innerhalb des AUTOSAR Service Discovery (SD) Moduls. Das Diagramm spezifiziert die Serialisierungsstruktur der „IPv6 SD Endpoint Option“ über einem 32-Bit-Raster (Bit-Offsets 0 bis 31).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Option besteht aus standardisierten Feldern:</p>\n<ul class=\"fig-list\"><li><strong>Length (=0x0015)</strong>: 16 Bit (Bit 0 bis 15 im ersten Word), fester Wert 21 Byte Nutzdatenlänge.\n</li><li><strong>Type (=0x26)</strong>: 8 Bit (Bit 16 bis 23 im ersten Word), Kennung des Optionstyps für IPv6 SD Endpoints.\n</li><li><strong>Reserved (=0x00)</strong>: 8 Bit (Bit 24 bis 31 im ersten Word), reserviertes Byte.\n</li><li><strong>IPv6-Address [128bit]</strong>: 128 Bit (16 Byte, vier aufeinanderfolgende 32-Bit-Worte), enthält die IPv6-Unicast- oder Multicast-Adresse des Endpunkts.\n</li><li><strong>Reserved (=0x00)</strong>: 8 Bit (Bit 0 bis 7 im sechsten Word), weiteres reserviertes Byte.\n</li><li><strong>L4-Proto (UDP/…)</strong>: 8 Bit (Bit 8 bis 15 im sechsten Word), Transportprotokollkennung (z. B. UDP).\n</li><li><strong>Port Number</strong>: 16 Bit (Bit 16 bis 31 im sechsten Word), L4-Portnummer des Endpunkts.\n</li></ul>\n<p class=\"fig-p\">Eine vertikale Maßlinie an der rechten Seite („Covered by Length (incl. Reserved)“) spannt über alle Felder ab der IPv6-Adresse bis einschließlich Port Number (Gesamtlänge 21 Byte bzw. 168 Bit).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische PDU-Feldbelegung ohne dynamische Kontrollfluss- oder Zustandsübergangssequenzen. Die Option wird als strukturierter Block innerhalb der Options-Sektion einer SOME/IP-SD-Nachricht serialisiert und deserialisiert. Der Sender codiert die IP-Adresse, das Transportprotokoll und den Zielport; der Empfänger wertet diese Daten zur Adressierung von Services oder Eventgruppen aus.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der Wire-Repräsentation der IPv6 SD Endpoint Option. Der Type-Identifikator ist zwingend auf 0x26 festgelegt. Das Längenfeld Length ist fest auf 0x0015 (21 Dezimal) codiert und deckt definitionsgemäß die nachfolgenden Felder ab: IPv6-Adresse (16 Byte) + Reserved (1 Byte) + L4-Proto (1 Byte) + Port Number (2 Byte) = 20 Byte zuzüglich des einleitenden Reserved-Bytes (1 Byte) = 21 Byte. Reservierte Felder müssen auf 0x00 gesetzt und beim Empfang ignoriert bzw. maskiert werden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-c7133db028d1e938", "to": "FIG-51aaf938ad360e0e", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-51aaf938ad360e0e", "to": "FIG-248db2caf0c8b86c", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
